public void moveZeroes(int[] nums) {
    int lt = 0, i = 0;
    while (i < nums.length) {
       if (nums[i] != 0) {
           swap(nums, lt, i);
           lt++;
           i++;
       } else {
           i++;
       }
    }
}

private void swap(int[] nums, int i, int j) {
    int temp = nums[i];
    nums[i] = nums[j];
    nums[j] = temp;
}

